/// <summary>
/// REQ-INV-105: copies the delivery instructions of the sales order to the customer invoice journal.
/// </summary>
[ExtensionOf(tableStr(CustInvoiceJour))]
final class CustInvoiceJour_DYLO_Extension
{
}

Method.Source:
/// <summary>
/// Initializes the invoice journal from the sales order and copies the delivery instructions.
/// </summary>
/// <param name = "salesTable">The sales order the invoice header is created from.</param>
/// <param name = "_salesParmTable">The sales parameter table record.</param>
public void initFromSalesTable(SalesTable salesTable, SalesParmTable _salesParmTable)
{
    next initFromSalesTable(salesTable, _salesParmTable);

    this.DYLO_DeliveryInstructions = salesTable.DYLO_DeliveryInstructions;
}
